-- ============================================================================
-- Our Partners — Bilingual Conversion (_ar/_fr) for ALL 6 partner pages
-- Idempotent. Arabic sourced from existing seed migrations (00008-00016).
-- Shared sections (services/why/gallery) get French translations.
-- Partner-specific sections get Arabic preserved; French left for CMS entry.
-- ============================================================================

DO $$
DECLARE
  v_pid uuid;
BEGIN
  -- #################################################################
  -- 1. LeFouilleurma  (/partners/lefouilleurma)
  -- #################################################################
  SELECT id INTO v_pid FROM pages WHERE slug = '/partners/lefouilleurma' LIMIT 1;
  IF v_pid IS NOT NULL THEN

    -- 1. HERO
    UPDATE page_sections SET content = '{"heading_ar":"LeFouilleurma","heading_fr":"LeFouilleurma","subheading_ar":"شريك وطني","subheading_fr":"Partenaire national","description_ar":"شريك وطني للجمعية المغربية لهواة البحث والاستكشاف، متخصص في بيع وشراء أجهزة الكشف عن المعادن والكنوز على المستوى الوطني.","description_fr":"Partenaire national de l''Association Marocaine des Amateurs de Recherche et d''Exploration, spécialisé dans la vente et l''achat de détecteurs de métaux et de trésors au niveau national.","backgroundImage":"","buttons":[{"id":"btn-pr-website","label_ar":"زيارة الموقع الإلكتروني","label_fr":"Visiter le site web","url":"https://www.lefouilleurma.ma","variant":"primary"},{"id":"btn-pr-contact","label_ar":"تواصل مع الشريك","label_fr":"Contacter le partenaire","url":"#prForm","variant":"secondary"}]}'::jsonb WHERE page_id = v_pid AND sort_order = 1;

    -- 2. ABOUT
    UPDATE page_sections SET content = '{"_renderer":"partnerAbout","eyebrow_ar":"عن LeFouilleurma","eyebrow_fr":"À propos de LeFouilleurma","heading_ar":"شريككم الموثوق في مجال التنقيب والاستكشاف","heading_fr":"Votre partenaire de confiance en prospection et exploration","paragraphs_ar":["LeFouilleurma هي شركة مغربية متخصصة في بيع وشراء أجهزة الكشف عن المعادن والكنوز. تقدم الشركة مجموعة واسعة من الأجهزة المتطورة لتلبية احتياجات الهواة والمحترفين على حد سواء.","نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة وطنية تهدف إلى توفير أحدث أجهزة الكشف والتنقيب لأعضاء الجمعية بأسعار تفضيلية."],"paragraphs_fr":["LeFouilleurma est une entreprise marocaine spécialisée dans la vente et l''achat de détecteurs de métaux et de trésors. L''entreprise propose une large gamme d''appareils avancés pour répondre aux besoins des amateurs et des professionnels.","Nous travaillons avec l''Association Marocaine des Amateurs de Recherche et d''Exploration dans le cadre d''un partenariat national visant à fournir les derniers équipements de détection et de prospection aux membres de l''association à des prix préférentiels."],"image":""}'::jsonb WHERE page_id = v_pid AND sort_order = 2;

    -- 3. SERVICES
    UPDATE page_sections SET content = '{"_renderer":"partnerServices","eyebrow_ar":"خدماتنا","eyebrow_fr":"Nos services","heading_ar":"ماذا نقدم؟","heading_fr":"Que proposons-nous ?","description_ar":"نقدم مجموعة متكاملة من الخدمات المتخصصة في مجال التنقيب والاستكشاف.","description_fr":"Nous offrons une gamme complète de services spécialisés en prospection et exploration.","cards":[{"title_ar":"التنقيب المعدني","title_fr":"Prospection minière","description_ar":"دراسات جيولوجية متقدمة للتنقيب عن المعادن والثروات الطبيعية في مختلف مناطق المغرب.","description_fr":"Études géologiques avancées pour la prospection des minéraux et des ressources naturelles dans les différentes régions du Maroc."},{"title_ar":"الدراسات الجيولوجية","title_fr":"Études géologiques","description_ar":"تحليل وتوثيق التكوينات الجيولوجية وتقديم استشارات متخصصة للمشاريع الاستكشافية.","description_fr":"Analyse et documentation des formations géologiques et conseil spécialisé pour les projets d''exploration."},{"title_ar":"رسم الخرائط","title_fr":"Cartographie","description_ar":"تصميم وإنتاج خرائط جيولوجية وطبوغرافية دقيقة باستخدام أحدث التقنيات الرقمية.","description_fr":"Conception et production de cartes géologiques et topographiques précises utilisant les dernières technologies numériques."},{"title_ar":"التحاليل المخبرية","title_fr":"Analyses en laboratoire","description_ar":"تحاليل متطورة للعينات المعدنية والصخرية باستخدام أحدث الأجهزة والتقنيات المخبرية.","description_fr":"Analyses avancées d''échantillons minéraux et rocheux utilisant les derniers équipements et techniques de laboratoire."}]}'::jsonb WHERE page_id = v_pid AND sort_order = 3;

    -- 4. WHY PARTNER
    UPDATE page_sections SET content = '{"_renderer":"partnerWhy","eyebrow_ar":"لماذا الشراكة معنا؟","eyebrow_fr":"Pourquoi un partenariat avec nous ?","heading_ar":"مميزات شراكتنا","heading_fr":"Les avantages de notre partenariat","description_ar":"نعمل جنبًا إلى جنب مع شركائنا لتحقيق النجاح المشترك.","description_fr":"Nous travaillons main dans la main avec nos partenaires pour atteindre le succès commun.","cards":[{"title_ar":"خبرة مهنية","title_fr":"Expertise professionnelle","description_ar":"نمتلك خبرة تمتد لسنوات في مجال التنقيب والاستكشاف المعدني بالمغرب.","description_fr":"Nous possédons une expérience de plusieurs années dans le domaine de la prospection et de l''exploration minière au Maroc."},{"title_ar":"شريك موثوق","title_fr":"Partenaire fiable","description_ar":"نلتزم بأعلى معايير الجودة والمهنية في جميع مشاريعنا وخدماتنا.","description_fr":"Nous respectons les plus hauts standards de qualité et de professionnalisme dans tous nos projets et services."},{"title_ar":"خدمات عالية الجودة","title_fr":"Services de haute qualité","description_ar":"نقدم خدمات متكاملة تلبي احتياجات شركائنا بأعلى مستوى من الدقة والكفاءة.","description_fr":"Nous offrons des services complets répondant aux besoins de nos partenaires avec le plus haut niveau de précision et d''efficacité."},{"title_ar":"تعاون وطني ودولي","title_fr":"Coopération nationale et internationale","description_ar":"نعمل في إطار تعاون وطني ودولي لتعزيز البحث والاستكشاف المعدني.","description_fr":"Nous travaillons dans le cadre d''une coopération nationale et internationale pour promouvoir la recherche et l''exploration minière."}]}'::jsonb WHERE page_id = v_pid AND sort_order = 4;

    -- 5. GALLERY
    UPDATE page_sections SET content = '{"_renderer":"partnerGallery","eyebrow_ar":"معرض الصور","eyebrow_fr":"Galerie photos","heading_ar":"صور من أعمالنا","heading_fr":"Photos de nos travaux","description_ar":"جانب من أنشطتنا ومشاريعنا المشتركة.","description_fr":"Un aperçu de nos activités et projets communs.","images":[{"id":"gimg-0","url":"","alt":""},{"id":"gimg-1","url":"","alt":""},{"id":"gimg-2","url":"","alt":""},{"id":"gimg-3","url":"","alt":""},{"id":"gimg-4","url":"","alt":""},{"id":"gimg-5","url":"","alt":""}]}'::jsonb WHERE page_id = v_pid AND sort_order = 5;

