    UPDATE page_sections SET content = '{"_renderer":"partnerCta","heading_ar":"هل أنت مهتم بالعمل مع هذا الشريك؟","heading_fr":"Intéressé par un partenariat ?","description":"","buttons":[{"id":"btn-pr-cta-0","label_ar":"زيارة الموقع الإلكتروني","label_fr":"Visiter le site web","url":"https://www.lefouilleurma.ma","variant":"primary"},{"id":"btn-pr-cta-1","label_ar":"تواصل مع الشريك","label_fr":"Contacter le partenaire","url":"#prForm","variant":"secondary"}]}'::jsonb WHERE page_id = v_pid AND sort_order = 8;

