    UPDATE page_sections SET content = '{"_renderer":"partnerAbout","eyebrow_ar":"عن SENOTEC","eyebrow_fr":"À propos de SENOTEC","heading_ar":"شريككم الموثوق في مجال التنقيب والاستكشاف","heading_fr":"Votre partenaire de confiance en prospection et exploration","paragraphs_ar":["SENOTEC هي شركة دولية متخصصة في تقديم الحلول التقنية والأمنية المتطورة. تمتلك الشركة خبرة واسعة في مجال أنظمة المراقبة والحماية الإلكترونية للمؤسسات والمنشآت.","نعمل مع الجمعية المغربية لهواة البحث والاستكشاف في إطار شراكة دولية تهدف إلى تعزيز الأمن والسلامة في الأنشطة الميدانية والاستكشافية."],"paragraphs_fr":["SENOTEC est une entreprise internationale spécialisée dans les solutions techniques et de sécurité avancées. L''entreprise possède une vaste expérience dans les systèmes de surveillance et de protection électronique pour les institutions et les installations.","Nous travaillons avec l''Association Marocaine des Amateurs de Recherche et d''Exploration dans le cadre d''un partenariat international visant à renforcer la sécurité dans les activités de terrain et d''exploration."],"image":""}'::jsonb WHERE page_id = v_pid AND sort_order = 2;

